import React, { useState } from 'react';

function TimeBlock({ id, title, time, icon, items = [], onUpdate }) {
  const [isEditing, setIsEditing] = useState(false);
  const [newItem, setNewItem] = useState({ category: '', description: '' });

  const categories = [
    'Работа', 'Учеба', 'Спорт', 'Отдых', 'Встречи',
    'Здоровье', 'Творчество', 'Дом', 'Семья', 'Друзья'
  ];

  const addItem = () => {
    if (newItem.category) {
      onUpdate([...items, { ...newItem, id: Date.now() }]);
      setNewItem({ category: '', description: '' });
    }
  };

  const removeItem = (itemId) => {
    onUpdate(items.filter(item => item.id !== itemId));
  };

  const getCategoryColor = (category) => {
    const colors = {
      'Работа': '#ff6b6b',
      'Учеба': '#4ecdc4',
      'Спорт': '#45b7d1',
      'Отдых': '#96ceb4',
      'Встречи': '#ffeaa7',
      'Здоровье': '#ff9ff3',
      'Творчество': '#feca57',
      'Дом': '#ffb8b8',
      'Семья': '#c56cf0',
      'Друзья': '#ffcccc'
    };
    return colors[category] || '#ddd';
  };

  return (
    <div className="time-block" style={{ borderColor: getCategoryColor(items[0]?.category) }}>
      <div className="block-header">
        <span className="block-icon">{icon}</span>
        <h3>{title}</h3>
        <span className="block-time">{time}</span>
      </div>

      <div className="block-content">
        {items.length > 0 ? (
          <ul className="items-list">
            {items.map(item => (
              <li key={item.id} className="item">
                <span
                  className="category-badge"
                  style={{ backgroundColor: getCategoryColor(item.category) }}
                >
                  {item.category}
                </span>
                {item.description && <span className="item-desc">{item.description}</span>}
                <button onClick={() => removeItem(item.id)} className="remove-btn">✕</button>
              </li>
            ))}
          </ul>
        ) : (
          <p className="empty-message">Нет записей</p>
        )}

        {isEditing && (
          <div className="add-item-form">
            <select
              value={newItem.category}
              onChange={(e) => setNewItem({...newItem, category: e.target.value})}
            >
              <option value="">Выберите категорию</option>
              {categories.map(cat => (
                <option key={cat} value={cat}>{cat}</option>
              ))}
            </select>

            <input
              type="text"
              placeholder="Описание (необязательно)"
              value={newItem.description}
              onChange={(e) => setNewItem({...newItem, description: e.target.value})}
            />

            <button onClick={addItem} className="add-btn">Добавить</button>
          </div>
        )}

        <button
          onClick={() => setIsEditing(!isEditing)}
          className="toggle-edit-btn"
        >
          {isEditing ? 'Отмена' : '+ Добавить'}
        </button>
      </div>
    </div>
  );
}

export default TimeBlock;
